from itertools import zip_longest


def transpose(text):
    rows = text.split("\n")
    output = []

    for column in zip_longest(*rows, fillvalue=None):
        cells = list(column)
        while cells and cells[-1] is None:
            cells.pop()
        output.append("".join(" " if cell is None else cell for cell in cells))

    return "\n".join(output)

